window.MONSTER_CHUNK_31 = [{"name":"Spyglass Archon","cr":3,"xp":800,"alignment":"LG","size":"Medium","type":"outsider","subtypes":["archon","extraplanar","good","lawful"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect evil"},{"type":"hone senses"},{"type":"low-light vision"}],"auras":["aura of menace (DC 13)","magic circle against evil"],"ac":15,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+2 armor, +2 Dex, +1 natural","hp":26,"hd":"4d10+4","hdvalue":4,"fort":2,"ref":6,"will":4,"save_mods":"+4 vs. poison","dr":"5/evil","immunities":["electricity","petrification"],"sr":14,"speed":[{"type":"land","speed":40},{"type":"fly","speed":40,"maneuverability":"good"}],"melee":"mwk longsword +5 (1d8+2/19-20), mwk short sword +5 (1d6+1/19-20)","ranged":"shortbow +6 (1d6/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect evil"},{"spell":"magic circle against evil"}]},{"frequency":"at-will","spells":[{"spell":"aid"},{"spell":"continual flame"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"message"}]},{"frequency":"3/day","spells":[{"spell":"darkness"},{"spell":"entropic shield"},{"spell":"undetectable alignment"}]}],"strength":14,"dexterity":15,"constitution":12,"intelligence":13,"wisdom":10,"charisma":9,"baseatk":4,"cmb":6,"cmd":18,"feats":[{"feat":"Skill Focus (Stealth)"},{"feat":"Two-Weapon Fighting"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Bluff","value":6},{"skill":"Fly","value":13},{"skill":"Knowledge (planes)","value":8},{"skill":"Perception","value":7},{"skill":"Sense Motive","value":7},{"skill":"Stealth","value":12}],"languages":["Celestial","Draconic","Infernal","truespeech"],"environments":["any (Heaven)"],"organizations":["solitary","pair"],"treasure":"standard (mwk longsword, mwk short sword, shortbow, leather armor)","description_visual":"The movements of this black-skinned humanoid are unnaturally quiet, clearly belonging to one used to slinking unseen and unheard through dark places. Ebon wings and a matching mask complete this figure's stealthy appearance.","group":"Archon","source":"Chronicle Of The Righteous","special_abilities":[{"type":"Hone Senses","kind":"Su","details":"Three times per day, a spyglass archon can concentrate its attention as a swift action. For a number of rounds equal to its Hit Dice (4 for most spyglass archons), the range of the spyglass archon's darkvision is doubled, it gains a +6 bonus on Perception checks, and it gains blindsense out to a range of 15 ft."}],"description":"Spyglass archons act as spies in the interests of Heaven. Though as lawful as any of their kin, spyglass archons use guile and stealth to uncover evil's plans and bring reports back to Heaven. Unlike hound archons, who act more as military scouts and sentinels, spyglass archons infiltrate enemy strongholds and observe agents of evil from scarcely an arm's-breadth away.\n\nSpyglass archons believe in law as strongly as they do in good, and are careful to act lawfully in their search for information. In places where law forbids a spyglass archon from entering a building and eavesdropping, it may hide in the shadows of public areas or conceal itself near windows to watch for evidence of evildoing. Once an archon has sufficient information to report, it returns to Heaven, where it shares its findings with its superiors.\n\nSince their tasks require discretion, spyglass archons train in multiple discreet fighting styles, and are as capable as any rogue of laying a foe low before she even notices the archon's presence. Specialized spell-like abilities aid the sleuths in this endeavor, and they are not above shrouding an enemy in magical darkness before descending upon her.\n\nSouls that become spyglass archons are solitary by nature, so they have few qualms about the isolation entailed by work. Most of their missions require intense concentration and skill, and are most easily undertaken by a single individual, but 2 spyglass archons might work together on extremely difficult, multipart missions.\n\nSpyglass archons are just over 5 ft. tall and weigh almost 120 pounds.","ecology":"","habitat_society":""},{"name":"Stone Idol","cr":3,"xp":800,"alignment":"N","size":"Diminutive","type":"construct","init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["stony mind (30 ft.)"],"ac":17,"ac_touch":13,"ac_flat_footed":17,"ac_mods":"-1 Dex, +4 natural, +4 size","hp":19,"hd":"3d10+3","hdvalue":3,"fort":1,"ref":0,"will":3,"dr":"5/-","immunities":["cold","electricity","fire","sonic"],"speed":[{"type":"land","speed":10}],"melee":"bite +8 (1d4+1)","space":"1 ft.","reach":"0 ft.","special_attacks":[{"type":"suggestive"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"animal trance"},{"spell":"detect snares and pits"},{"spell":"magic stone"}]},{"frequency":"1/day","spells":[{"spell":"bear's endurance"},{"spell":"hold person"}]},{"frequency":"3/day","spells":[{"spell":"doom"},{"spell":"hypnotic pattern"},{"spell":"reduce person"}]}],"strength":12,"dexterity":8,"intelligence":7,"wisdom":14,"charisma":14,"baseatk":3,"cmb":-2,"cmd":9,"feats":[{"feat":"Alertness"},{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":7},{"skill":"Stealth","value":11}],"languages":["understands creator's language (cannot speak)"],"sq":[{"type":"inanimate"},{"type":"share abilities"}],"environments":["any"],"organizations":["solitary"],"treasure":"incidental","description_visual":"Doubtlessly once an impressive piece, time and cracks mar the sculpted stone visage of some sneering lord. Flecks of onyx glisten within its eyes, gazing across the gulf into ages past.","group":"Idol","source":"AP 27","special_abilities":[{"type":"Inanimate","kind":"Ex","details":"An idol is effectively a statuette and does little to suggest otherwise. Spending most of its existence perfectly motionless, a stationary idol is indistinguishable from a normal inanimate object. Unless noted in its description, an idol can make use of the majority of its special abilities without moving, though the round after it does so observers can make a DC 25 Perception check to notice minute hints-magical glimmers, minute contortions, etc.-suggesting that the idol is actually animate. Overt actions, such as an idol moving or attacking, make its nature obvious to witnesses, and to others who make a Perception check (as previously noted) even 1 round after it moves."},{"type":"Preserve Memory","kind":"Su","details":"Any sentient creature with a Charisma of 14 or higher can copy one of its memories into a stone idol. To do so, the creature must remain in contact with a stone idol for 1 minute and concentrate on a memory to be duplicated. This memory must be 5 minutes or shorter and be of an actual event; imaginings cannot be reproduced. After a memory has been duplicated, it remains in the stone idol until a new memory is recorded. A memory held by a stone idol can be altered via the spell modify memory. A memory held within a stone idol can be viewed by any creature that comes into mental contact with the construct and by the use of detect thoughts, mind-reading effects, or similar abilities, even one redirected by its stony mind ability."},{"type":"Share Abilities","kind":"Su","details":"An idol can share any spell-like ability that would normally only affect itself (as the caster) with any ally within 5 ft. The idol's creator or allies familiar with its abilities may request the idol grant them specific powers on its turn. Spell-like abilities usable in this way are marked with an asterisk. Skills In addition to the challenge of detecting a stationary idol, these constructs gain a +4 racial bonus on Stealth checks made to hide amid the materials that comprise their bodies."},{"type":"Stony Mind","kind":"Su","details":"Any divination spell targeting a creature or object within 30 ft. of a stone idol instead targets the construct. Thus, for the purposes of any spell that reveals auras, those affected are treated as being under the effects of the spell misdirection, while spells like detect thoughts receive nothing more than vague impressions. Should detect thoughts or another mind-reading effect target a stone idol that contains a memory, the ability user instantly gains the memory held within."},{"type":"Suggestive","kind":"Su","details":"Those fascinated by a stone idol's animal trance or hypnotic pattern spell-like ability become highly susceptible to the suggestions of others nearby. Any creature can make a suggestion (as per the spell suggestion) to a fascinated creature, who must then make a DC 15 Will save or proceed to follow the suggestion. Any creature who makes a suggestion is understood by the fascinated creature, as per the spell tongues or speak with animals. A suggestion lasts for 1 hour, even if a creature is no longer being fascinated. A fascinated creature follows only the first suggestion it fails its saving throw against and no additional suggestions. The DC is Charisma-based and includes a +2 racial bonus."}],"description":"Rarely seen in civilized lands, stone idols rest among the ruins of ancient civilizations, the sole inheritors of incredible secrets and lost lore. Sculpted in the images of forgotten lords and mythic beasts, these statuettes transfix their foes with a suggestion of what wonders their polished eyes might once have witnessed.","ecology":"","habitat_society":""},{"name":"Technic League Hireling","cr":3,"xp":800,"race":"Human","classes":[{"class":"rogue","level":4}],"alignment":"CN","size":"Medium","type":"humanoid","subtypes":["human"],"init":4,"ac":18,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+3 armor, +4 Dex, +1 shield","hp":25,"hd":"4d8+4","hdvalue":4,"fort":5,"ref":9,"will":7,"defensive_abilities":["evasion","trap sense +1","uncanny dodge"],"speed":[{"type":"land","speed":30}],"melee":"dagger +4 (1d4+1/19-20)","ranged":"dagger +7 (1d4+1/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"}],"strength":13,"dexterity":18,"constitution":12,"intelligence":14,"wisdom":8,"charisma":10,"baseatk":3,"cmb":6,"cmd":21,"cmd_special":"can't be tripped","feats":[{"feat":"Alertness"},{"feat":"Deft Hands"},{"feat":"Great Fortitude"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Appraise","value":7},{"skill":"Bluff","value":7},{"skill":"Climb","value":8},{"skill":"Disable Device","value":15,"special":"+14 vs. electronic devices"},{"skill":"Escape Artist","value":11},{"skill":"Knowledge (engineering)","value":6},{"skill":"Knowledge (local)","value":6},{"skill":"Perception","value":8},{"skill":"Sense Motive","value":8},{"skill":"Sleight of Hand","value":13},{"skill":"Stealth","value":11},{"skill":"Survival","value":3},{"skill":"Swim","value":5}],"languages":["Common","Giant","Hallit","Orc"],"sq":[{"type":"implanted tracker chip"},{"type":"rogue talents","details":"ledge walker, trap spotter"},{"type":"trapfinding","details":"+2"}],"environments":["any ruins (Numeria)"],"organizations":["solitary"],"treasure":"none","description_visual":"This woman's once-fine garments are tattered and stained with unnatural fluids, but her protective gear is carefully maintained.","source":"Numeria Land Of Fallen Stars","special_abilities":[{"type":"Black E-Pick","kind":"Ex","details":"This electronic lockpick allows the user to attempt Disable Device checks against electronic devices and grants its user a +1 competence bonus on the check. Thieves' tools don't apply to Disable Device checks against electronic devices. An e-pick has 10 charges; using the e-pick as part of a Disable Device check consumes one charge. An e-pick weighs 1 pound and is worth 100 gp."},{"type":"Implanted Tracker Chip","kind":"Ex","details":"This chip allows its carrier to be tracked remotely with a chipfinder. Finding evidence of it requires a full-round search of the carrier and a successful DC 30 Perception check. Extracting the chip requires a slashing weapon and deals 1 point of damage to the carrier."}],"description":"Long experience with the threats of Silver Mount often leaves Technic League members reluctant to risk their own lives in exploration. Rather, when they gain access to a new chamber in the Mount or other trove of lost technology, they sometimes rely on hirelings and specialized slaves. Also called canaries, metal rats, and silver divers, these delvers are valued for their skill but still seen as expendable. While most hire on voluntarily, offering their services in exchange for coin and adventure, some are adventurers who were caught trespassing in the Technic League's domain, and now pay for their continued existence with this risky form of servitude.\n\nHirelings are searched for any sign of contraband whenever they exit the Mount. Attempts to hide technology bring harsh, public punishment as a warning to others.\n\nThe Technic League secretly implants tracking devices in most metal rats to prevent them from escaping with technological secrets, attributing the scar to injections given to protect against exotic plagues and poisons..","ecology":"","habitat_society":"","gear":"potions of cure light wounds [2], potion of delay poison, acid [2], alchemist's fire, antitoxin, smokesticks [2], mwk studded leather, mwk buckler, dagger, cloak of resistance +1, backpack, black e-pick, climber's kit, crowbar, everburning torch, grappling hook, magnifying glass, masterwork thieves' tools, signal whistle, silk rope [100 ft.], sunrod [2], tindertwig [4], waterskin"},{"name":"Tidepool Dragon","cr":3,"xp":800,"alignment":"CN","size":"Tiny","type":"dragon","subtypes":["aquatic"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":15,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+1 Dex, +2 natural, +2 size","hp":30,"hd":"4d12+4","hdvalue":4,"fort":5,"ref":7,"will":1,"immunities":["paralysis","sleep"],"speed":[{"type":"land","speed":10},{"type":"fly","speed":30,"maneuverability":"average"},{"type":"swim","speed":60}],"melee":"bite +6 (1d3), 2 claws +6 (1d3 plus attach)","space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"breath weapon","details":"5-ft. line, 2d6 fire damage, Reflex DC 13 for half, usable every 1d4 rounds"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"freedom of movement","details":"self only"}]}],"spellsknown_caster_level":4,"spellsknown_concentration":5,"spellsknown":[{"spell_level":2,"spell_slots":4,"spells":[{"spell":"slipstream"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"hydraulic push"},{"spell":"obscuring mist"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"dancing lights"},{"spell":"daze"},{"spell":"detect poison"},{"spell":"mage hand"},{"spell":"touch of fatigue"}]}],"strength":11,"dexterity":13,"constitution":13,"intelligence":8,"wisdom":14,"charisma":14,"baseatk":4,"cmb":1,"cmd":14,"feats":[{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Fly","value":12},{"skill":"Knowledge (nature)","value":6},{"skill":"Perception","value":9},{"skill":"Survival","value":9},{"skill":"Swim","value":15}],"languages":["Common","Draconic"],"sq":[{"type":"amphibious"}],"environments":["warm coastlines"],"organizations":["solitary","pair","clutch (3-6)"],"treasure":"none","description_visual":"This small draconic creature seems better suited for the waves than wind, its wings sweeping along its body like massive fins. Light from the water refracts off its resilient-looking cerulean hide as it snaps crustacean-like claws.","group":"Dragon","source":"AP 55","special_abilities":[{"type":"Attach","kind":"Ex","details":"When a tidepool dragon hits with a claw attack, it automatically grapples its foe, dealing automatic damage with that claw each round."},{"type":"Breath Weapon","kind":"Su","details":"When a tidepool dragon uses its breath weapon underwater, it creates a 10-foot cone of superheated water rather than a line of fire (as noted above). This effect deals the breath weapon's damage to any creatures in the cone's area, though victims can still save to take only half damage."}],"description":"Aquatic dragons similar in size and fickleness to faerie dragons and pseudodragons, tidepool dragons rule as whimsical tyrants over miniature realms comprising coral forests, sand dune mountains, and low-tide menageries. Preferring to inhabit coastal regions throughout the world's warmer climes, these dragon-kin make their lairs amid balmy lagoons and hidden coves, favoring any seaside setting devoid of stronger predators. A combination of chitinous shell-similar in shade to that of a blue crab-and scales the color of clear tropical waters covers every tidepool dragon, the shade deepening through twilight hues to a shade as dark as a ocean abyss.\n\nTidepool dragons typically measure about 2 ft. long and weigh approximately 14 pounds. They are known to live for about 300 years.\n\nEcology\n\nDespite their size, tidepool dragons are hardy and well suited to their environment. Their sweeping fin-wings work equally well both above and beneath the water. While underwater, these dragons use their fins to make languid, powerful strokes, propelling them forward in graceful bursts, but the strong, flexible musculature beneath the fins also allows them to make quick, dramatic turns essential in pursing eels, small fish, and other agile prey. Above the water these same appendages work like wings, the membranous skin spreading over bones and cartilage to catch currents of air. Many observers who have glimpsed these creatures both above and below the waves claim that they don't fly so much as swim through the skies. The tiny dragons' dense muscle mass, particularly in their tails, allows them to create momentum strong enough to break the surface of the water and send them skyward in their characteristic glides. Although they prefer to eat fish, tidepool dragons often use their flight to chase seabirds off the surface of the waves and high into the sky, while the small, tough teeth that line every tidepool dragon's mouth can easily crack the hard shells of crabs and other shellfish.\n\nThe tidepool dragon is amphibious, possessing both gills and lungs, and can exist outside of water indefinitely. While it is in flight, muscles stretch its gill slits so they lie flat along the body, decreasing resistance to the wind. At the apex of the dragon's complex respiratory system, near the base of the creature's throat, a pair of small bones hang down. Tidepool dragons can vibrate these bones at an almost unthinkable speed, and the furious motion gives off intense heat. They can then draw water through their bodies from their gills and push it out of their mouths. As this torrent of water passes the vibrating bones, it heats to temperatures beyond scalding, capable of burning flesh and even melting glass. Even when not submerged, tidepool dragons can draw moisture from the air through their gills to power their breath weapons. But despite the potency of a tidepool dragon's breath when used in flight or on land, these creatures usually employ their breath weapons while underwater. When the dragons are submerged, their scalding gout of water diffuses into a small cloud of boiling water, allowing them to affect entire schools of fish or other groups of prey in a single boiling burst.\n\nHabitat & Society\n\nTidepool dragons get their name from their tendency to frequent small coastal pools, where they bask and sleep because they are usually safe from other predators there and their shell-like hides blend well with the brilliant colors of local aquatic fauna. Those attempting to capture or otherwise contain a tidepool dragon find it a challenging task, as the creature's freedom of movement ability makes most nets, ropes, and simple attempts to grab it near useless. \"Slippery as a tide wyrm\" is a phrase often bandied about by sailors and other seafarers when trying to cross treacherously wet decks or wrestle the rigging of a loose and blowing sail.\n\nDespite being almost impossible to catch, tidepool dragons can be bargained with rather readily, as their interests, while fickle, are quite simple. Those seeking tidepool dragons' favor-or, at least, hoping not to incur their mischief-can make offerings to the dragon, typically in the form of coins, gems, or particularly shiny shells so that the miniature wyrms can mimic their larger kin. Additionally, most tidepool dragons enjoy rare fish that cannot be found in their home waters, or fruits and vegetables from far inland that they've never sampled.\n\nCapricious and self-serving, these miniature dragons possess a less savory reputation than their faerie dragon or pseudodragon cousins, making enemies as easily as they make allies. Highly territorial, most tidepool dragons take offense if the waters and coasts near their lairs are intruded upon, blasting trespassers with their breath weapons or perpetrating various pranks upon them. If satisfied, though-typically by being bribed with shiny baubles or salty food-tidepool dragons can prove quite helpful, serving other creatures for the promise of more rewards. Clever sailors have been known to leave trails of enticing foods in their ships' wakes in an effort to draw the attention of tidepool dragons. If successful, a vessel can gain a valuable helper, capable of acting as a lookout both far above and far below the water. Several aquatic species, such as merfolk, tritons, aquatic elves, and even sahuagin, also recognize the benefits of keeping tidepool dragons as allies, and some explorers have recorded colonies of such aquatic humanoids where well-fed clutches of these dragons act as sentries or scouts.\n\nWhen left to their own devices, tidepool dragons live in small coastal caves, usually in mated pairs or related family clutches. These lairs always contain exit shafts into the sky beyond since tidepool dragon eggs and new hatchlings are a favorite prey of bunyips. Tidepool dragon eggs are about the size of a chicken or crocodile egg, but are marked with the same colors that will eventually grace the hatchlings' scales. Parents hatch their young and then raise them until they are capable of surviving on their own, around age 3. At that point, young tidepool dragons set off to find mates and indulge their species' rampant curiosity. Single youths also band together to form non-familial pods for hunting and adventure.\n\nTidepool Dragons as Familiars Although difficult to approach, tidepool dragons sometimes choose to serve as the familiars of unruly spellcasters and those who go out of their way to feed them rich or exotic foods. Spellcasters of 7th level or higher with an alignment within one step of chaotic neutral can gain a tidepool dragon as a familiar by taking the Improved Familiar feat.","ecology":"Despite their size, tidepool dragons are hardy and well suited to their environment. Their sweeping fin-wings work equally well both above and beneath the water. While underwater, these dragons use their fins to make languid, powerful strokes, propelling them forward in graceful bursts, but the strong, flexible musculature beneath the fins also allows them to make quick, dramatic turns essential in pursing eels, small fish, and other agile prey. Above the water these same appendages work like wings, the membranous skin spreading over bones and cartilage to catch currents of air. Many observers who have glimpsed these creatures both above and below the waves claim that they don't fly so much as swim through the skies. The tiny dragons' dense muscle mass, particularly in their tails, allows them to create momentum strong enough to break the surface of the water and send them skyward in their characteristic glides. Although they prefer to eat fish, tidepool dragons often use their flight to chase seabirds off the surface of the waves and high into the sky, while the small, tough teeth that line every tidepool dragon's mouth can easily crack the hard shells of crabs and other shellfish.\n\nThe tidepool dragon is amphibious, possessing both gills and lungs, and can exist outside of water indefinitely. While it is in flight, muscles stretch its gill slits so they lie flat along the body, decreasing resistance to the wind. At the apex of the dragon's complex respiratory system, near the base of the creature's throat, a pair of small bones hang down. Tidepool dragons can vibrate these bones at an almost unthinkable speed, and the furious motion gives off intense heat. They can then draw water through their bodies from their gills and push it out of their mouths. As this torrent of water passes the vibrating bones, it heats to temperatures beyond scalding, capable of burning flesh and even melting glass. Even when not submerged, tidepool dragons can draw moisture from the air through their gills to power their breath weapons. But despite the potency of a tidepool dragon's breath when used in flight or on land, these creatures usually employ their breath weapons while underwater. When the dragons are submerged, their scalding gout of water diffuses into a small cloud of boiling water, allowing them to affect entire schools of fish or other groups of prey in a single boiling burst.","habitat_society":"Tidepool dragons get their name from their tendency to frequent small coastal pools, where they bask and sleep because they are usually safe from other predators there and their shell-like hides blend well with the brilliant colors of local aquatic fauna. Those attempting to capture or otherwise contain a tidepool dragon find it a challenging task, as the creature's freedom of movement ability makes most nets, ropes, and simple attempts to grab it near useless. \"Slippery as a tide wyrm\" is a phrase often bandied about by sailors and other seafarers when trying to cross treacherously wet decks or wrestle the rigging of a loose and blowing sail.\n\nDespite being almost impossible to catch, tidepool dragons can be bargained with rather readily, as their interests, while fickle, are quite simple. Those seeking tidepool dragons' favor-or, at least, hoping not to incur their mischief-can make offerings to the dragon, typically in the form of coins, gems, or particularly shiny shells so that the miniature wyrms can mimic their larger kin. Additionally, most tidepool dragons enjoy rare fish that cannot be found in their home waters, or fruits and vegetables from far inland that they've never sampled.\n\nCapricious and self-serving, these miniature dragons possess a less savory reputation than their faerie dragon or pseudodragon cousins, making enemies as easily as they make allies. Highly territorial, most tidepool dragons take offense if the waters and coasts near their lairs are intruded upon, blasting trespassers with their breath weapons or perpetrating various pranks upon them. If satisfied, though-typically by being bribed with shiny baubles or salty food-tidepool dragons can prove quite helpful, serving other creatures for the promise of more rewards. Clever sailors have been known to leave trails of enticing foods in their ships' wakes in an effort to draw the attention of tidepool dragons. If successful, a vessel can gain a valuable helper, capable of acting as a lookout both far above and far below the water. Several aquatic species, such as merfolk, tritons, aquatic elves, and even sahuagin, also recognize the benefits of keeping tidepool dragons as allies, and some explorers have recorded colonies of such aquatic humanoids where well-fed clutches of these dragons act as sentries or scouts.\n\nWhen left to their own devices, tidepool dragons live in small coastal caves, usually in mated pairs or related family clutches. These lairs always contain exit shafts into the sky beyond since tidepool dragon eggs and new hatchlings are a favorite prey of bunyips. Tidepool dragon eggs are about the size of a chicken or crocodile egg, but are marked with the same colors that will eventually grace the hatchlings' scales. Parents hatch their young and then raise them until they are capable of surviving on their own, around age 3. At that point, young tidepool dragons set off to find mates and indulge their species' rampant curiosity. Single youths also band together to form non-familial pods for hunting and adventure.\n\nTidepool Dragons as Familiars Although difficult to approach, tidepool dragons sometimes choose to serve as the familiars of unruly spellcasters and those who go out of their way to feed them rich or exotic foods. Spellcasters of 7th level or higher with an alignment within one step of chaotic neutral can gain a tidepool dragon as a familiar by taking the Improved Familiar feat."},{"name":"Tikoloshe","cr":3,"xp":800,"alignment":"CE","size":"Small","type":"undead","subtypes":["aquatic"],"init":2,"senses":[{"type":"blindsense","modifier":"60 ft."},{"type":"blindsight","modifier":"30 ft."}],"ac":15,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+2 Dex, +2 natural, +1 size","hp":26,"hd":"4d8+8","hdvalue":4,"fort":2,"ref":3,"will":3,"defensive_abilities":["channel resistance +2","water diffusion"],"dr":"5/slashing","immunities":["undead traits"],"resists":[{"type":"fire","value":10}],"weaknesses":["blind"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":30}],"speed_mod":"waverider","melee":"bite +6 (1d4+2), 2 slams +6 (1d3+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"trickster's torment"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"invisibility"}]}],"strength":14,"dexterity":15,"intelligence":8,"wisdom":15,"charisma":13,"baseatk":3,"cmb":4,"cmd":18,"cmd_special":"+4 vs. trip","feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"}],"skills":[{"skill":"Climb","value":9},{"skill":"Perception","value":12},{"skill":"Stealth","value":13},{"skill":"Swim","value":10}],"languages":["Common","Polyglot"],"environments":["any oceans","any rivers","warm forests"],"organizations":["solitary","gang (2-8)","clan (9-20)"],"treasure":"standard","description_visual":"The water churns and splashes as a small, stocky humanoid surges forth, gnashing rows of needle-like teeth, its eye sockets merely deep gouges. As if it were one with the water itself, it darts quickly forward, shouting curses and swinging its fists.","source":"AP 40","special_abilities":[{"type":"Blind","details":"A tikoloshe has no eyes and is blind. All creatures beyond the range of its hearing-based blindsense and blindsight abilities have total concealment against it."},{"type":"Trickster's Torment","kind":"Su","details":"Once per day, a tikoloshe can curse another living creature. As a standard action, the tikoloshe makes a melee touch attack and unless the target makes a DC 15 Will save, the target is treated as if under the effect of bestow curse, except that the curse's duration is only 24 hours. A creature can only suffer from one tikoloshe's curse at a time. The save DC is Charisma-based."},{"type":"Water Diffusion","kind":"Ex","details":"When in water at least 2 ft. deep, a tikoloshe's body seems to diffuse into and become part of the water, granting it concealment (20% miss chance) as if under the effect of blur. This effect ends immediately upon entering shallower water or setting foot on land."},{"type":"Waverider","kind":"Ex","details":"Up to 3 times per day, a tikoloshe can swim up to 30 ft. as a swift action. It doesn't provoke an attack of opportunity for this movement."}],"description":"Cruel and spiteful, tikoloshe (singular and plural) are small undead that haunt tropical waterways and jungles, preying on travelers and villagers alike with their magical abilities and appetite for harm. Tikoloshe stand no higher than a gnome or a human child, but their bodies are dense and muscular; many have large potbellies and arms long enough for their knuckles to score the dirt as they walk. Their creation leaves them with blackened, eyeless sockets, but tikoloshe can \"see\" using their giant, bat-like ears. Their skin is smooth and shines whether wet or dry. Tikoloshe are genderless; they stand about 4 ft. tall and weigh almost 150 pounds. Ecology Tikoloshe are created from the corpses of the dead, but are not mindless like some zombies or skeletons. Creating a tikoloshe requires a ritual wherein a spellcaster places a newly dead humanoid body in a specially crafted clay basin of shallow water and then bores a hole through the corpse's eyes with a red-hot poker. As the creator casts magical fire through this aperture, the surrounding water is rapidly drawn into the body. As it does, the corpse shrinks and changes, casting off all vestiges of its former features and replacing them with those of all tikoloshe. The conf licting forces of fire and water animate the tikoloshe and instill it with its well-known hostility. The tikoloshe's creator can exact one service from its new creation, but afterward has no control over the creature. A tikoloshe's undead traits and resistance to fire make it an ideal servant for many tasks. Some are forced to mine rare minerals deep underwater or to capture exotic elemental creatures on fiery planes. Other creators use tikoloshe as sinister pawns to curse or even kill hated adversaries. Once released from servitude, tikoloshe prefer to inhabit waterways and shallow seabeds where they can rest undisturbed and where they can surprise travelers, fisherfolk, and swimmers. When partially submerged, a tikoloshe's body merges with the surrounding water, making it difficult to see and battle. When not near water, tikoloshe dwell in shallow holes under rocks and large trees, and even under porches and raised buildings in small villages. While their bodies don't require food to sustain themselves, tikoloshe enjoy stalking and eating smaller creatures like birds, frogs, and rabbits. They particularly relish killing monkeys, as they enjoy the nearly human screams the unfortunate animals make. Tikoloshe will sometimes make ghastly fetishes of their kills and leave them on the fences or doorsteps of local settlements to hint at their presence and cause fear among those they seek to torment. As a result, many jungle tribes place rare or semiprecious stones on the thresholds of their homes as an offering for tikoloshe to eat, claiming that doing so protects that home against the creature's wrath. Although some scholars dismiss such practices as abject superstition, druids and clerics of the Mwangi Expanse assert that by ingesting a potent fragment of earth, tikoloshe are able to soothe the opposing elemental forces within them and thus still their malevolent nature. Habitat & Society Tikoloshe form gangs and clans whenever possible, knowing that their ability to cause mayhem is greater in numbers. Individually, they haunt inhabited areas using their invisibility to cause strange, uncanny incidents like unlocking doors to animal pens, moving and breaking household objects, and spoiling food. Tikoloshe often use their curse to bestow bad luck on those that they haunt. Watching from their invisible perches, from beneath beds, and even from inside closets and cupboards, the tikoloshe take spiteful glee in observing those whom they have rendered suddenly clumsy, weak, or otherwise inept as they fumble even the simplest of tasks. Many tikoloshe use their powers for more than mischief, however, and can prove a serious threat to both residents and travelers of the Mwangi Expanse. When fighting as a pack or clan, tikoloshe use their rapid swimming to close with foes, quickly swarming a single target and dragging it underwater. On land, groups of tikoloshe use invisibility to get close to opponents, seeking to curse as many enemies as possible before losing the element of surprise. They are cunning enough to use physically debilitating curses on heavily armed folk and mind-harming curses on those who they think might be spellcasters. Individual tikoloshe always try to flee when faced with organized resistance. If tracked or cornered, tikoloshe plead for their lives by offering a service to their captors, usually the same one that was exacted from them upon their creation. Those who accept a tikoloshe's offer may indeed benefit from the creature's service, but they must also be very cautious, as tikoloshe are not bound by any promises they make once their original commitment to their creator has been fulfilled. Cunning tikoloshe are known to barter their services for their lives, but only to buy enough time for their new masters to turn their backs. Variant Tikoloshe Depending on the ritual used and the quality of the materials, some tikoloshe look different than the standard dwarf-gremlin variety. Some look like horrid Small werebears in hybrid form, or like a worm-like creature with a dog's head and golden tongue. These variants may or may not have the burned-out eyeholes of the \"standard\" tikoloshe. Creating Tikoloshe The process of creating a tikoloshe is more complex than for animating most undead creatures, but requires the same fundamental magic. Ultimately, the creation process culminates in the casting of the spell create undead. In addition to the normal components of the spell, creating a tikoloshe requires the equipment and process previously noted, adding 1 day of effort and 100 gold pieces to the typical requirements of the spell. Typically, a caster loses control over a tikoloshe after the undead performs one service for him, though creators of level 15 or higher retain control. Tikoloshe in Mythology The tikoloshe is an evil zombie or water spirit depicted as a trickster in tales throughout Southern Africa. Able to hurl curses and turn invisible by swallowing pebbles, tikoloshe are described as playing all manner of poltergeist-like tricks on people, although some tales depict them assaulting sleeping women or biting off toes during the night, giving the creatures a more sinister quality. Descriptions of the tikoloshe vary from myth to myth, but most emphasize its gremlin-like features, small stature, and the burned-out holes where its eyes should be. Cultural historians claim that the latter links the creature definitively to Zulu mythology because of the importance of fire in most Zulu legends. To this day, the tikoloshe is synonymous with misfortune, and the creature's name is invoked whenever a person suffers bad luck.","ecology":"Tikoloshe are created from the corpses of the dead, but are not mindless like some zombies or skeletons. Creating a tikoloshe requires a ritual wherein a spellcaster places a newly dead humanoid body in a specially crafted clay basin of shallow water and then bores a hole through the corpse's eyes with a red-hot poker. As the creator casts magical fire through this aperture, the surrounding water is rapidly drawn into the body. As it does, the corpse shrinks and changes, casting off all vestiges of its former features and replacing them with those of all tikoloshe. The conf licting forces of fire and water animate the tikoloshe and instill it with its well-known hostility. The tikoloshe's creator can exact one service from its new creation, but afterward has no control over the creature. A tikoloshe's undead traits and resistance to fire make it an ideal servant for many tasks. Some are forced to mine rare minerals deep underwater or to capture exotic elemental creatures on fiery planes. Other creators use tikoloshe as sinister pawns to curse or even kill hated adversaries. Once released from servitude, tikoloshe prefer to inhabit waterways and shallow seabeds where they can rest undisturbed and where they can surprise travelers, fisherfolk, and swimmers. When partially submerged, a tikoloshe's body merges with the surrounding water, making it difficult to see and battle. When not near water, tikoloshe dwell in shallow holes under rocks and large trees, and even under porches and raised buildings in small villages. While their bodies don't require food to sustain themselves, tikoloshe enjoy stalking and eating smaller creatures like birds, frogs, and rabbits. They particularly relish killing monkeys, as they enjoy the nearly human screams the unfortunate animals make. Tikoloshe will sometimes make ghastly fetishes of their kills and leave them on the fences or doorsteps of local settlements to hint at their presence and cause fear among those they seek to torment. As a result, many jungle tribes place rare or semiprecious stones on the thresholds of their homes as an offering for tikoloshe to eat, claiming that doing so protects that home against the creature's wrath. Although some scholars dismiss such practices as abject superstition, druids and clerics of the Mwangi Expanse assert that by ingesting a potent fragment of earth, tikoloshe are able to soothe the opposing elemental forces within them and thus still their malevolent nature.","habitat_society":"Tikoloshe form gangs and clans whenever possible, knowing that their ability to cause mayhem is greater in numbers. Individually, they haunt inhabited areas using their invisibility to cause strange, uncanny incidents like unlocking doors to animal pens, moving and breaking household objects, and spoiling food. Tikoloshe often use their curse to bestow bad luck on those that they haunt. Watching from their invisible perches, from beneath beds, and even from inside closets and cupboards, the tikoloshe take spiteful glee in observing those whom they have rendered suddenly clumsy, weak, or otherwise inept as they fumble even the simplest of tasks. Many tikoloshe use their powers for more than mischief, however, and can prove a serious threat to both residents and travelers of the Mwangi Expanse. When fighting as a pack or clan, tikoloshe use their rapid swimming to close with foes, quickly swarming a single target and dragging it underwater. On land, groups of tikoloshe use invisibility to get close to opponents, seeking to curse as many enemies as possible before losing the element of surprise. They are cunning enough to use physically debilitating curses on heavily armed folk and mind-harming curses on those who they think might be spellcasters. Individual tikoloshe always try to flee when faced with organized resistance. If tracked or cornered, tikoloshe plead for their lives by offering a service to their captors, usually the same one that was exacted from them upon their creation. Those who accept a tikoloshe's offer may indeed benefit from the creature's service, but they must also be very cautious, as tikoloshe are not bound by any promises they make once their original commitment to their creator has been fulfilled. Cunning tikoloshe are known to barter their services for their lives, but only to buy enough time for their new masters to turn their backs. Variant Tikoloshe Depending on the ritual used and the quality of the materials, some tikoloshe look different than the standard dwarf-gremlin variety. Some look like horrid Small werebears in hybrid form, or like a worm-like creature with a dog's head and golden tongue. These variants may or may not have the burned-out eyeholes of the \"standard\" tikoloshe. Creating Tikoloshe The process of creating a tikoloshe is more complex than for animating most undead creatures, but requires the same fundamental magic. Ultimately, the creation process culminates in the casting of the spell create undead. In addition to the normal components of the spell, creating a tikoloshe requires the equipment and process previously noted, adding 1 day of effort and 100 gold pieces to the typical requirements of the spell. Typically, a caster loses control over a tikoloshe after the undead performs one service for him, though creators of level 15 or higher retain control. Tikoloshe in Mythology The tikoloshe is an evil zombie or water spirit depicted as a trickster in tales throughout Southern Africa. Able to hurl curses and turn invisible by swallowing pebbles, tikoloshe are described as playing all manner of poltergeist-like tricks on people, although some tales depict them assaulting sleeping women or biting off toes during the night, giving the creatures a more sinister quality. Descriptions of the tikoloshe vary from myth to myth, but most emphasize its gremlin-like features, small stature, and the burned-out holes where its eyes should be. Cultural historians claim that the latter links the creature definitively to Zulu mythology because of the importance of fire in most Zulu legends. To this day, the tikoloshe is synonymous with misfortune, and the creature's name is invoked whenever a person suffers bad luck."},{"name":"Trollhound","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"magical beast","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":11,"ac_flat_footed":14,"ac_mods":"+1 Dex, +4 natural","hp":30,"hd":"4d10+8","hdvalue":4,"hp_mods":["regeneration 3 (acid or fire)"],"fort":6,"ref":5,"will":2,"speed":[{"type":"land","speed":40}],"melee":"bite +8 (1d10+6 plus disease and trip)","space":"5 ft.","reach":"5 ft.","strength":18,"dexterity":13,"constitution":15,"intelligence":2,"wisdom":11,"charisma":6,"baseatk":4,"cmb":9,"cmb_special":"+2 vs. grapple","cmd":18,"cmd_special":"+2 vs. grapple","feats":[{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":8},{"skill":"Stealth","value":5},{"skill":"Survival","value":1,"special":"+5 scent tracking"}],"environments":["cold mountains"],"organizations":["solitary","pair","pack (3-8)"],"treasure":"incidental","description_visual":"Foul-smelling fluids ooze from weeping sores across the scaly skin of this squat, powerful, and vaguely canine beast.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Disease","kind":"Ex","details":"A trollhound's saliva is an infectious brew of contagion. Creatures bitten by a trollhound are often afflicted with bloodfire fever, a disease characterized by deep internal pain, as if the victim's blood were on fire. Additional symptoms include loss of muscular coordination, pus-filled blisters, and overall lethargy and fatigue. Trolls and trollhounds alike are immune to bloodfire fever, even though trollhounds often exhibit the pus-filled blisters that come with the disease. Bloodfire fever: Bite-injury; save Fort DC 14; onset 1 day; frequency 1/day; effect 1d3 Str damage, 1d3 Dex damage, and target is fatigued; cure 2 consecutive saves. The save DC is Constitution-based."}],"description":"Slavering and voracious, trollhounds seem to be trolls in smaller canine form, and indeed, are often found as pets among gangs and tribes of trolls. Requiring vast amounts of food to fuel their regenerative metabolisms, packs of wild trollhounds range far and wide through the mountains of the north, their ravenous hunger driving them to hunt and consume any prey they can track down and kill.\n\nA typical trollhound stands 4 ft. tall at the shoulder, has short but powerful legs, and weighs around 350 pounds. A trollhound's skin is somewhat scaly, with patches of rough, greenish-black fur. It has oversized jaws with a pronounced underbite, and its eyes are normally a dull, hateful orange.\n\nTrollhounds are believed to be the outcome of infusing particularly ferocious worgs with alchemically prepared troll blood. The resulting beast loses the worg's wicked intelligence but gains the ability to regenerate even the most grievous wounds, except those inf licted by fire or acid. Whatever their origin, trollhounds breed true and are often raised by trolls.\n\nTrollhounds are fearless on the hunt and in combat, relying on their ability to regenerate to carry them through. Not even the threat of fire is enough to repel them, as the beasts are too dull to recognize the danger it poses. Nevertheless, fire is one of the most effective tools in combating trollhounds, and canny hunters know to burn every last remnant of a slain trollhound, for as is true of trolls, even the smallest piece of trollhound flesh can eventually regrow back into a full-sized beast.\n\nTrollhounds are most often found in the company of trolls, who breed the beasts as hunters, guards, pets, and food. Trollhounds seem to have an affinity for their savage masters, and tamed trollhounds always regard trolls as alpha members of the pack. A trollhound will never attack a troll without cause-although trolls often enjoy violent roughhousing with these creatures nonetheless.","ecology":"","habitat_society":""},{"name":"Twigjack","cr":3,"xp":800,"alignment":"CE","size":"Tiny","type":"fey","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":17,"ac_touch":15,"ac_flat_footed":14,"ac_mods":"+3 Dex, +2 natural, +2 size","hp":27,"hd":"5d6+10","hdvalue":5,"fort":3,"ref":7,"will":6,"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":30}],"melee":"spear +3 (1d4-1/x3) or   2 claws +7 (1d4-1)","space":"2-1/2 ft.","reach":"0 ft. (5 ft. with spear)","special_attacks":[{"type":"sneak attack","details":"+2d6"},{"type":"splinterspray"}],"strength":8,"dexterity":16,"constitution":15,"intelligence":11,"wisdom":14,"charisma":13,"baseatk":2,"cmb":3,"cmd":12,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Skill Focus (Stealth)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Climb","value":7},{"skill":"Disable Device","value":8},{"skill":"Knowledge (nature)","value":8},{"skill":"Perception","value":10},{"skill":"Stealth","value":22}],"languages":["Common","Sylvan"],"sq":[{"type":"bramble jump"},{"type":"woodland stride"}],"environments":["temperate forests"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"standard","description_visual":"This tiny, vaguely humanoid creature seems to be made completely of bundles of sticks wound with thorny vines.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Bramble Jump","kind":"Su","details":"A twigjack can travel short distances between brambles, shrubs, or thickets as if via dimension door as part of a move action. The twigjack must begin and end this movement while in an area of at least light undergrowth. The twigjack can travel in this manner up to 60 ft. per day. This movement must be used in 10-foot increments and doesn't provoke attacks of opportunity."},{"type":"Splinterspray","kind":"Ex","details":"A twigjack can eject a barrage of splinters and brambles from its body three times per day as a standard action. This effect creates a 15-foot conical burst of jagged splinters, dealing 4d6 points of piercing damage to all creatures in the area. A DC 14 Reflex saving throw halves this damage. The save DC is Constitution-based."}],"description":"Deep in old-growth forests, twigjacks spend their time tormenting intruders and wreaking havoc on settlers. Maladjusted protectors of the wood, these malicious fey constantly threaten any attempts to civilize the wild. Twigjacks delight in breaking wagon wheels from expansionists' caravans, snapping hunters' bows, and sabotaging isolated cabins and villages. Although they possess a keen intellect, few creatures, even other fey, can tolerate these twig-born creatures for long. Treants especially find twigjacks bothersome, and resent any suggestion that they are related. Equally, twigjacks resent being considered plants, and are proud of their fey heritage. Twigjacks sometimes go out of their way to impress dryads, an effort that is rebuffed almost every time. But some spriggans, quicklings, and other evil fey associate with twigjacks, and while goblins fear and distrust the creatures, bugbears often bully them into service.\n\nGnarled sticks bundled by vines and brambles form a twigjack's entire body. Atop its head, a mossy growth not unlike hair sprouts. The creature's eyes appear as vacant dark knotholes, and its mouth is just a canyon of splintered and broken sticks bisecting its face. Leaves and sprigs of new growth randomly sprout from the creature's body.","ecology":"","habitat_society":""},{"name":"Unicorn","cr":3,"xp":800,"alignment":"CG","size":"Large","type":"magical beast","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"auras":["magic circle against evil"],"ac":15,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+3 Dex, +3 natural, -1 size | +2 deflection vs. evil","hp":34,"hd":"4d10+12","hdvalue":4,"fort":7,"ref":7,"will":6,"save_mods":"+2 vs. evil","immunities":["charm","compulsion","poison"],"speed":[{"type":"land","speed":60}],"melee":"gore +8 (1d8+4), 2 hooves +5 (1d3+2)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"powerful charge","details":"gore, 2d8+8"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect evil","details":"as free action"},{"spell":"light"}]},{"frequency":"1/day","spells":[{"spell":"cure moderate wounds"},{"spell":"greater teleport","details":"within its forest territory"},{"spell":"neutralize poison"}]},{"frequency":"3/day","spells":[{"spell":"cure light wounds"}]}],"strength":18,"dexterity":17,"constitution":16,"intelligence":11,"wisdom":21,"charisma":24,"baseatk":4,"cmb":9,"cmd":22,"cmd_special":"+4 vs. trip","feats":[{"feat":"Multiattack"},{"feat":"Weapon Focus (horn)"}],"skills":[{"skill":"Acrobatics","value":8},{"skill":"Perception","value":10},{"skill":"Stealth","value":8},{"skill":"Survival","value":7,"special":"+10 in forests"}],"languages":["Common","Sylvan"],"sq":[{"type":"magical strike"},{"type":"wild empathy","details":"+17"}],"environments":["temperate forests"],"organizations":["solitary","mated pair","blessing (3-6)"],"treasure":"none","description_visual":"This magnificent beast looks like a white horse, but with a goat's beard and a single long ivory horn on its brow.","source":"PFRPG Bestiary","special_abilities":[{"type":"Magic Circle against Evil","kind":"Su","details":"This ability continually duplicates the effect of the spell. The unicorn cannot suppress this ability."},{"type":"Magical Strike","kind":"Ex","details":"A unicorn's gore attack is treated as a magic good weapon for the purposes of damage reduction."},{"type":"Wild Empathy","kind":"Su","details":"This works like the druid's wild empathy class feature, except the unicorn has a +6 racial bonus on the check. Unicorns with druid levels add this racial modifier to their wild empathy checks."}],"description":"Unicorns are fierce, intelligent creatures of the forest, noble beasts who keep their own counsel and typically appear only to defend their homes against evil. They universally shun all creatures except for good-aligned fey, good-aligned humanoid women, and the woodlands' native animals, though they may fight alongside other good creatures against common enemies. A typical unicorn is 8 ft. long and 5 ft. tall at the shoulder, weighing 1,200 pounds.\n\nUnicorns mate for life, and the pairs generally make their homes in specific glades or dells within the vast forests they protect (these regions can cover anywhere from a few dozen square miles to hundreds). They allow good and neutral creatures to pass through, hunt for food, or reside in their woods unharmed, but evil creatures and those who damage the local ecosystem more than necessary through sport hunting or commercial logging are swiftly driven out or killed. On rare occasions, lone unicorns without mates or whose partners have been slain have been known to adopt young women of exceptionally pure virtue as surrogates, allowing the women to ride on their backs and becoming their guardians and protectors for life. This bond generally ends amiably if the woman becomes more committed to someone else-such as a lover or child-giving rise to the myth that unicorns only befriend virgins.\n\nA unicorn's horn is the focus for its powers, and in order to use its spell-like abilities on other creatures the unicorn must touch them with it. Evil creatures greatly value unicorn horns as reagents for healing potions and other dark rites, and a single powdered unicorn horn counts as 1,600 gp when used as a component for crafting healing magic.","ecology":"","habitat_society":""},{"name":"Urdefhan","cr":3,"xp":800,"alignment":"NE","size":"Medium","type":"outsider","subtypes":["native"],"init":1,"senses":[{"type":"darkvision","modifier":"120 ft."}],"ac":16,"ac_touch":11,"ac_flat_footed":15,"ac_mods":"+3 armor, +1 Dex, +2 natural","hp":25,"hd":"3d10+9","hdvalue":3,"fort":6,"ref":4,"will":4,"defensive_abilities":["negative energy affinity"],"dr":"5/good or silver","immunities":["death effects","disease","fear","level drain"],"resists":[{"type":"acid","value":10}],"sr":14,"speed":[{"type":"land","speed":30}],"melee":"rhoka sword +8 (1d8+6/18-20), bite +2 (1d4+2 plus 2 Str) or  bite +7 (1d4+4 plus 2 Str)","ranged":"composite longbow +4 (1d8+4/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blood drain","details":"1 Con"}],"spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"feather fall"}]},{"frequency":"3/day","spells":[{"spell":"align weapon"},{"spell":"death knell"},{"spell":"ray of enfeeblement"}]}],"strength":19,"dexterity":12,"constitution":17,"intelligence":14,"wisdom":13,"charisma":14,"baseatk":3,"cmb":7,"cmd":18,"feats":[{"feat":"Iron Will"},{"feat":"Weapon Focus (rhoka sword)"}],"skills":[{"skill":"Intimidate","value":8},{"skill":"Knowledge (dungeoneering)","value":5},{"skill":"Knowledge (planes)","value":8},{"skill":"Knowledge (religion)","value":8},{"skill":"Perception","value":7},{"skill":"Ride","value":4},{"skill":"Sense Motive","value":7},{"skill":"Survival","value":7}],"languages":["Aklo","Undercommon"],"sq":[{"type":"daemonic pact"}],"environments":["any land (Abaddon)"],"organizations":["solitary","pair","gang (3-12)","cult (13-30 plus 2-6 fighters of 2nd-4th level, 1-4 necromancer wizards of 3rd-6th level, 1 cleric high priest of 5th-9th level, 8-12 skavelings, and 1-3 ceustodaemons)"],"treasure":"none","description_visual":"This fanged humanoid has hideously transparent skin, revealing the vivid colors of internal organs and ivory bones inside its body.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Daemonic Pact","kind":"Su","details":"Urdefhans are infused with daemonic energy; as an immediate action, an urdefhan can attempt to allow this energy to consume its soul (50% chance of success per attempt). If it succeeds, the urdefhan dies and releases a 5-foot-radius burst of negative energy that deals 2d6 points of damage (DC 14 Reflex half). The save DC is Con-based."},{"type":"Strength Damage","kind":"Su","details":"An urdefhan's bite drains vitality, turning the skin and muscle around the wound transparent and causing 2 points of Strength damage unless the target succeeds on a DC 14 Fortitude save. The flesh remains transparent until the Strength damage is healed, but this doesn't have any other effects. The save DC is Constitution-based."}],"description":"Infused with fell energies from Abaddon, urdefhans are an unsightly race dedicated to war. They have developed many strange weapons, but none are more iconic than the two-bladed rhoka sword. Rhoka swords are exotic onehanded melee weapons-all urdefhans are proficient in their use. With such weapons, an urdefhan seeks to inf lict as much death as possible upon the world before it perishes, so that its daemonic lords are pleased. Most male urdefhans are sterile-as a result, the women often turn to conjured daemons for mates. The products of such unions are usually typical urdefhans, but sometimes result in half-fiend urdefhans-these monsters usually rise to positions of great power in their violent society.","ecology":"","habitat_society":"","gear":"studded leather, rhoka sword, composite longbow (+4 Str) with 20 arrows"},{"name":"Vampiric Mist","cr":3,"xp":800,"alignment":"NE","size":"Medium","type":"aberration","subtypes":["air","water"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"sense blood"}],"ac":14,"ac_touch":14,"ac_flat_footed":10,"ac_mods":"+4 Dex","hp":30,"hd":"4d8+12","hdvalue":4,"fort":4,"ref":5,"will":5,"defensive_abilities":["amorphous"],"dr":"5/magic","weaknesses":["vulnerable to fire"],"speed":[{"type":"fly","speed":50,"maneuverability":"perfect"}],"melee":"touch +7 (bleed and blood siphon)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bleed","details":"1d6"}],"dexterity":19,"constitution":16,"intelligence":7,"wisdom":13,"charisma":10,"baseatk":3,"feats":[{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":12},{"skill":"Perception","value":8},{"skill":"Stealth","value":11}],"languages":["Aklo"],"sq":[{"type":"blood overdose"},{"type":"misty form"}],"environments":["temperate swamps","temperate underground","warm swamps","warm underground"],"organizations":["solitary","pair","gang (3-6)"],"treasure":"incidental","description_visual":"A cloud of crimson vapor reeking of fresh blood hangs in the air, reaching out with lashing claws.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Blood Siphon","kind":"Ex","details":"A vampiric mist drains blood with each melee touch attack dealing 1d3 points of Constitution damage. Every time a vampiric mist damages a creature in this way, it heals 1d8 hit points. Hit points healed in excess of its maximum are gained as temporary hit points, to a maximum amount equal to its Constitution score. These temporary hit points last for 1 hour."},{"type":"Blood Overdose","kind":"Su","details":"When a vampiric mist gorges on blood to an extent that it gains temporary hit points, it moves much more quickly. It gains a +2 bonus to its Armor Class and on Reflex saves, and can take one additional move action each round."},{"type":"Misty Form","kind":"Ex","details":"A vampiric mist's body is composed of a semisolid red mist similar in consistency to thick foam. The vampiric mist doesn't have a Strength score, and it cannot manipulate or wear solid objects. This form grants it the amorphous defensive ability, and allows it to move through areas as small as 1 inch in diameter with no reduction to its speed. The creature can speak in a hissing voice. A vampiric mist cannot enter water or other fluids, and is treated as a creature two size categories smaller than its actual size (Tiny for most vampiric mists) for the purposes of how wind affects it."},{"type":"Sense Blood","kind":"Ex","details":"A vampiric mist can immediately sense the presence of warm-blooded creatures in a 60-foot radius as if by scent. It can detect exposed blood within a mile."}],"description":"Often mistaken for a vampire in gaseous form or an unusual type of air elemental, the vampiric mist is in fact a strange form of aberrant life. With an amorphous body that consists as much of fluid as it does of air, this creature dwells in swamps or moist underground regions where its vulnerability to heat isn't as much of a concern.\n\nAlthough somewhat intelligent, vampiric mists don't form societies. They sometimes form into small gangs, but even then they show little interest in working together. Much of a vampiric mist's time is spent seeking prey-a pursuit that the monster often shows great creativity in accomplishing. The creatures' propensity for taking on vague, skeletal forms of the creatures whose blood they drink only further adds to their mystique and fuels rumors that they have connections to the undead. Indeed, many vampiric mists enjoy using this common misconception to their advantage, causing foes to use foolish tactics-such as tricking spellcasters into using positive energy against them as if they were undead monsters.","ecology":"","habitat_society":""},{"name":"Vermlek","cr":3,"xp":800,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":-1,"senses":[{"type":"blindsense","modifier":"30 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":15,"ac_touch":9,"ac_flat_footed":15,"ac_mods":"+3 armor, -1 Dex, +3 natural","hp":30,"hd":"4d10+8","hdvalue":4,"fort":8,"ref":0,"will":5,"defensive_abilities":["abandon flesh","flesh armor","negative energy affinity"],"dr":"5/cold iron or good","immunities":["electricity","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"sr":14,"speed":[{"type":"land","speed":30},{"type":"burrow","speed":20}],"melee":"longsword +6 (1d8+2/19-20), bite +1 (1d6+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"inhabit body"}],"spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"gentle repose"},{"spell":"summon","details":"level 2, 1d4 dretches, 50%"}]},{"frequency":"3/day","spells":[{"spell":"mass inflict light wounds"},{"spell":"spider climb"}]}],"strength":15,"dexterity":9,"constitution":14,"intelligence":12,"wisdom":13,"charisma":12,"baseatk":4,"cmb":6,"cmb_special":"+4 vs. grapple","cmd":15,"feats":[{"feat":"Deceitful"},{"feat":"Great Fortitude"}],"skills":[{"skill":"Bluff","value":10},{"skill":"Disguise","value":10,"special":"+18 when inhabiting a corpse"},{"skill":"Escape Artist","value":6,"special":"+14 when not inhabiting a corpse"},{"skill":"Knowledge (religion)","value":8},{"skill":"Perception","value":8},{"skill":"Sense Motive","value":8},{"skill":"Use Magic Device","value":8}],"languages":["Abyssal","Common","telepathy 100 ft."],"environments":["any (Abyss; battlefields and graveyards)"],"organizations":["solitary","nest (2-20)"],"treasure":"standard","description_visual":"A corpulent man reels on his feet as if drunk, but a closer inspection reveals the horrific truth-he's not so much reeling as he is seething from within, as if his internal organs were coiling and writhing like a knot of greased snakes. Suddenly, with a hideous retching and tearing sound, the man's face blooms out like a rotten flower and a pallid, five-jawed worm extrudes itself from the ragged hole in the neck where, only a moment before, a head sat.","group":"Demon","source":"Book of the Damned V2","special_abilities":[{"type":"Abandon Flesh","kind":"Su","details":"As a swift action, a vermlek can abandon an inhabited body, crawling hideously out of its host and leaving behind an empty sack of skin and bits of gristle. In so doing, it absorbs much of the body's flesh to heal itself, restoring 2d6+3 hit points. A vermlek cannot later reclaim this body with its inhabit body ability."},{"type":"Flesh Armor","kind":"Su","details":"When a vermlek wears a humanoid body (see inhabit body, below), it treats the dead flesh and muscle as armor and gains a +3 armor bonus to its AC."},{"type":"Inhabit Body","kind":"Su","details":"A vermlek can crawl into the body of any dead Medium humanoid, consuming and replacing the bulk of the humanoid's skeleton and internal organs as it does so. This process takes 1d4 rounds for the vermlek to complete, during which it is considered flat-footed. Once the process is complete, the vermlek appears for all practical purposes to be a living but hideously obese version of the previous humanoid-it gains a +8 racial bonus on Disguise checks to appear as a normal humanoid while wearing a dead body in this manner, but doesn't gain any of the abilities that the dead creature possessed in life, including natural attacks, unusual movement types, or bonuses to natural armor. It loses its own burrow speed while inhabiting a body, but gains the ability to wield weapons or wear armor shaped for humanoids (although note that the armor bonus granted by wearing armor doesn't stack with the bonus granted by the vermlek's flesh armor ability)."},{"type":"Negative Energy Affinity","kind":"Ex","details":"A vermlek is healed by negative energy and harmed by positive energy as if it were an undead creature."}],"description":"The hideous vermlek demon is one of the lower-ranking members of the demon race, barely above the dretch in power but remarkably more ambitious and intelligent than its pudgy lesser kin. They wriggle and crawl in nauseating numbers in many Abyssal battlefields or graveyards, impatiently awaiting a chance to find a humanoid body to inhabit. Outside of a host body, a vermlek appears like a fatheaded worm with four long tails, each of which ends in a wriggling nest of long filaments. In this form, the vermlek cannot wield weapons, and its bite and spell-like abilities are its only offensive options. A typical vermlek is 7 ft. long (with its filaments giving it a further 3 ft. of length) and weighs 90 pounds.\n\nEcology Vermleks form from the souls of those who habitually violated the dead in life, such as graverobbers, necromancers, and necrophiles.\n\nOn the Abyss, the vermleks are countless in number. A single sinful soul can spawn dozens if not hundreds of these demons in much the same way that the body the soul leaves behind spawns maggots. A newly formed vermlek can flop and writhe through the stinking Abyssal necropolises and swamps and boneyards for eons before it finds a body to inhabit, but it's much more common for a vermlek to be \"harvested\" by a more powerful demon for use in a battle. Vermleks harvested in this manner are carried in huge steel cages on the backs of enormous fiendish beasts of burden, such as retrievers, and either sold to powerful Material Plane spellcasters or used in battle against humanoid foes. The classic use for vermleks in such cases is to open the cages containing the worm demons after an initial skirmish or battle so that they can slither out onto the battlefield and claim bodies from the dead, thus recycling the carrion for use in the next battle to come. As vermleks can only inhabit the bodies of humanoids, this tactic isn't as common on the Abyss (where demons typically fight themselves or other outsiders), but in regions of Golarion where demons hold sway, such as the Worldwound or Tanglebriar, their use can be a particularly demoralizing form of psychological combat.\n\nThe process by which a vermlek inhabits and controls a dead humanoid is partially biological, partially necromantic.\n\nA vermlek's body is boneless and exceptionally elastic-it can wriggle into a body through the mouth, a wound, or any other opening in less than a minute, eating the bones and organs within with noisy rapidity. It then settles into the cavity thus created, extending its four tails down into the torso and eventually into the hollowed arms and legs of its host, whereupon the filaments at the tips of these tails weave through nerves and muscle like a puppet's strings.\n\nThe vermlek can immediately use the body to move about, wield weapons, speak, and otherwise interact with society.\n\nThe creature can control the coiling and wriggling of its body to keep its host appearing humanoid, but it can do little about the size of its body-humanoids inhabited by a vermlek always look hideously obese. Worse, the host body, which remains dead, rots normally-a vermlek that doesn't maintain its body's freshness with gentle repose must abandon the rotting flesh 7 days after inhabiting it to seek out a new host.\n\nVermleks know that a keen eye that peers into the mouth of a host can quickly undo their deceptions, and as a result they tend to mutter or mumble when speaking to keep from opening their mouths too wide. Many use veils, helms, or scarves to hide their mouths. When confronted in combat, though, a vermlek in a host body quickly abandons its disguise, extending its hideous worm head out through the host's mouth to give itself a secondary bite attack-doing so ruins the host body for further disguise purposes.\n\nHabitat & Society Vermleks can often be found at the sites of vast battlefields on the Abyss where wars with humanoids (fiendish, celestial, or otherwise) have occurred. These sites are particularly common on Kurnugia, where the fiendish gnolls of Lamashtu constantly bicker and war with one another, and on Ishiar, where the fiendish human pirates and scoundrels that dwell upon that ocean's islands wage eternal war. These demons generally spawn in Abyssal realms like Everglut, Uligor, and the Spiral Path, where demon lords associated with the dead or worms rule, and they can be found in great number in those regions' vast graveyards and necropolises.\n\nAlthough they are often used as disposable infantry in mass battles, vermleks themselves have little taste for such activities and, left to their own desires, prefer to live in hiding among humanoids on the Material Plane if they can find their way into that realm. A vermlek fortunate enough to find itself on the Material Plane enjoys disguising itself as a laborer, gravedigger, dungsweeper, or any other lowclass role in which it can blend in while still having access to the city's dead. A vermlek's ghoulish and taboo lusts are only magnified by its creation, and on the Material Plane, the arrival of one of these filthy demons in a society almost always presages a sudden upswing in scandalously violent or distasteful crime.","ecology":"Vermleks form from the souls of those who habitually violated the dead in life, such as graverobbers, necromancers, and necrophiles.\n\nOn the Abyss, the vermleks are countless in number. A single sinful soul can spawn dozens if not hundreds of these demons in much the same way that the body the soul leaves behind spawns maggots. A newly formed vermlek can flop and writhe through the stinking Abyssal necropolises and swamps and boneyards for eons before it finds a body to inhabit, but it's much more common for a vermlek to be \"harvested\" by a more powerful demon for use in a battle. Vermleks harvested in this manner are carried in huge steel cages on the backs of enormous fiendish beasts of burden, such as retrievers, and either sold to powerful Material Plane spellcasters or used in battle against humanoid foes. The classic use for vermleks in such cases is to open the cages containing the worm demons after an initial skirmish or battle so that they can slither out onto the battlefield and claim bodies from the dead, thus recycling the carrion for use in the next battle to come. As vermleks can only inhabit the bodies of humanoids, this tactic isn't as common on the Abyss (where demons typically fight themselves or other outsiders), but in regions of Golarion where demons hold sway, such as the Worldwound or Tanglebriar, their use can be a particularly demoralizing form of psychological combat.\n\nThe process by which a vermlek inhabits and controls a dead humanoid is partially biological, partially necromantic.\n\nA vermlek's body is boneless and exceptionally elastic-it can wriggle into a body through the mouth, a wound, or any other opening in less than a minute, eating the bones and organs within with noisy rapidity. It then settles into the cavity thus created, extending its four tails down into the torso and eventually into the hollowed arms and legs of its host, whereupon the filaments at the tips of these tails weave through nerves and muscle like a puppet's strings.\n\nThe vermlek can immediately use the body to move about, wield weapons, speak, and otherwise interact with society.\n\nThe creature can control the coiling and wriggling of its body to keep its host appearing humanoid, but it can do little about the size of its body-humanoids inhabited by a vermlek always look hideously obese. Worse, the host body, which remains dead, rots normally-a vermlek that doesn't maintain its body's freshness with gentle repose must abandon the rotting flesh 7 days after inhabiting it to seek out a new host.\n\nVermleks know that a keen eye that peers into the mouth of a host can quickly undo their deceptions, and as a result they tend to mutter or mumble when speaking to keep from opening their mouths too wide. Many use veils, helms, or scarves to hide their mouths. When confronted in combat, though, a vermlek in a host body quickly abandons its disguise, extending its hideous worm head out through the host's mouth to give itself a secondary bite attack-doing so ruins the host body for further disguise purposes.","habitat_society":"Vermleks can often be found at the sites of vast battlefields on the Abyss where wars with humanoids (fiendish, celestial, or otherwise) have occurred. These sites are particularly common on Kurnugia, where the fiendish gnolls of Lamashtu constantly bicker and war with one another, and on Ishiar, where the fiendish human pirates and scoundrels that dwell upon that ocean's islands wage eternal war. These demons generally spawn in Abyssal realms like Everglut, Uligor, and the Spiral Path, where demon lords associated with the dead or worms rule, and they can be found in great number in those regions' vast graveyards and necropolises.\n\nAlthough they are often used as disposable infantry in mass battles, vermleks themselves have little taste for such activities and, left to their own desires, prefer to live in hiding among humanoids on the Material Plane if they can find their way into that realm. A vermlek fortunate enough to find itself on the Material Plane enjoys disguising itself as a laborer, gravedigger, dungsweeper, or any other lowclass role in which it can blend in while still having access to the city's dead. A vermlek's ghoulish and taboo lusts are only magnified by its creation, and on the Material Plane, the arrival of one of these filthy demons in a society almost always presages a sudden upswing in scandalously violent or distasteful crime."},{"name":"Violet Fungus","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"plant","init":-1,"senses":[{"type":"low-light vision"}],"ac":15,"ac_touch":9,"ac_flat_footed":15,"ac_mods":"-1 Dex, +6 natural","hp":30,"hd":"4d8+12","hdvalue":4,"fort":7,"ref":0,"will":1,"immunities":["plant traits"],"speed":[{"type":"land","speed":10}],"melee":"4 tentacles +4 (1d4+1 plus rot)","space":"5 ft.","reach":"10 ft.","strength":12,"dexterity":8,"constitution":16,"wisdom":11,"charisma":9,"baseatk":3,"cmb":4,"cmd":13,"environments":["any underground"],"organizations":["solitary","pair","grove (3-12)"],"treasure":"incidental","description_visual":"This mushroom grows from a bed of tentacular roots. Deep violet tendrils slither out of the dozens of fissures in its pointed cap.","source":"PFRPG Bestiary","special_abilities":[{"type":"Rot","kind":"Ex","details":"A creature struck by a violet fungus's tentacle must succeed on a DC 15 Fortitude save or the flesh around the point of contact swiftly begins to rot away, exposing raw bone with shocking swiftness. This hideous affliction causes 1d4 points of Strength damage and 1d4 points of Constitution damage. This is a poison effect. The save DC is Constitution-based."}],"description":"The violet fungus is one of the most notorious and feared dangers of the world's caves. A traveler can often see signs of the violet fungus in those who dwell or hunt in places where these carnivorous fungi lurk. In these folk, deep and hideous scars mar bodies where entire furrows of flesh seem scooped away-the marks of a close encounter with a violet fungus. A violet fungus feeds on the rot and decay of organic matter, but unlike most fungi, they are not passive consumers of corruption. A violet fungi's tendrils can strike with unexpected swiftness, and are coated with a virulent venom that causes flesh to rot and decay with nauseating speed. This potent poison, if left untreated, can cause the flesh of an entire arm or leg to drop away in no time at all, leaving behind only warm bones that soon rot into corruption as well. Although violet fungi are mobile, they only move to attack or to hunt for prey. A violet fungus that has a steady supply of rot to sup upon is generally content to remain in one place. Many underground-dwelling cultures take advantage of this penchant, particularly troglodytes and vegepygmies, and keep multiple violet fungi in key junctions and entrances to their caverns as guardians, making sure to keep them well fed with carrion to prevent them wandering farther into the den in search of food. Some species of shriekers are relatively similar in appearance to violet fungi, although they lack the tentacular branches. It's not uncommon to find shriekers and violet fungi growing in the same grove-especially in areas where other creatures cultivate the fungi as guardians. A violet fungus is 4 ft. tall and weighs 50 pounds. Violet Venom Although a violet fungus's tentacles swiftly grow inert after the mushroom is slain, they can be wielded as Medium-sized whips for 2d6 minutes after being harvested from the creature. These whips inf lict rot on anything they touch-including the wielder of the deadly weapon-and both save DCs to resist and effects are identical to the stats presented above. A DC 25 Craft (alchemy) check and 250 gp worth of reagents can preserve the venom somewhat, although the procedure dilutes it signif icantly. Violet Venom: Poison- contact; save Fort DC 13, frequency 1/minute for 6 minutes, effect 1d2 Strength and 1d2 Con damage; cure 1 save; cost 800 gp.","ecology":"","habitat_society":""},{"name":"Walrus","cr":3,"xp":800,"alignment":"N","size":"Large","type":"animal","init":0,"senses":[{"type":"low-light vision"}],"ac":17,"ac_touch":9,"ac_flat_footed":17,"ac_mods":"+8 natural, -1 size","hp":30,"hd":"4d8+12","hdvalue":4,"fort":7,"ref":4,"will":2,"speed":[{"type":"land","speed":10},{"type":"swim","speed":40}],"melee":"bite +8 (1d8+7)","space":"10 ft.","reach":"5 ft.","strength":21,"dexterity":11,"constitution":16,"intelligence":2,"wisdom":13,"charisma":6,"baseatk":3,"cmb":9,"cmd":19,"cmd_special":"can't be tripped","feats":[{"feat":"Endurance"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Perception","value":7},{"skill":"Swim","value":17}],"sq":[{"type":"hold breath"}],"environments":["cold oceans"],"organizations":["solitary","pair","herd (3-24)"],"treasure":"none","description_visual":"Two long tusks jut from the mouth of this bulky, bewhiskered creature. It walks clumsily on flippers instead of ft.","source":"PFRPG Bestiary 4","description":"Walruses normally have gray or brown hides, fading to nearly white when immersed in cold water, and turning pink from increased blood flow when basking in the sun. A thick layer of blubber serves as protection from both predators and cold. A typical male walrus weighs 1 to 2 tons and measures 10 ft. in length, with females about a third lighter and about 9 ft. long. Both sexes have tusks up to 3 ft. long, and stiff whiskers used to feel out the hiding places of shellfish. A walrus lives up to 40 years. Owing to their fearsome tusks, prodigious strength, and willingness to fight as a herd, only the most aggressive or hungry polar predators risk attacking an adult walrus. People hunt walruses for meat and for their tusks, valued for their worth as ivory and as impressive trophies in their own right.","ecology":"","habitat_society":""},{"name":"Wasp Swarm","cr":3,"xp":800,"alignment":"N","size":"Diminutive","type":"vermin","subtypes":["swarm"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":15,"ac_flat_footed":14,"ac_mods":"+1 Dex, +4 size","hp":31,"hd":"7d8","hdvalue":7,"fort":5,"ref":3,"will":3,"defensive_abilities":["swarm traits"],"immunities":["weapon damage"],"weaknesses":["swarm traits"],"speed":[{"type":"land","speed":5},{"type":"fly","speed":40,"maneuverability":"good"}],"melee":"swarm (2d6 plus poison)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"distraction","details":"DC 13"},{"type":"poison"}],"strength":1,"dexterity":13,"constitution":10,"wisdom":12,"charisma":9,"baseatk":5,"skills":[{"skill":"Fly","value":11},{"skill":"Perception","value":9}],"sq":[{"type":"swarm traits"},{"type":"vermin traits"}],"environments":["temperate forests"],"organizations":["solitary","pair","fury (3-6 swarms)","maelstrom (7-12 swarms)"],"treasure":"none","description_visual":"A low, ominous buzz announces the arrival of a mass of many thousands of angry, stinging wasps.","group":"Wasp","source":"PFRPG Bestiary","special_abilities":[{"type":"Poison","kind":"Ex","details":"Swarm-injury; save Fort DC 13; frequency 1/round for 4 rounds; effect 1 Dexterity damage; cure 1 save. The save DC is Constitution-based."}],"description":"A wasp swarm is a flying mass of thousands of carnivorous wasps. In such large numbers, they become voracious hunters, capable of taking down large creatures with their venom-filled stings. While a wasp swarm is capable of inf licting hundreds of stings, its true danger arises from its insatiable appetite for meat.\n\nWasp swarms surround and attack any living prey in their paths, and are swift to seek out new prey once their anger is aroused. An enraged wasp swarm often loses track of its hive or the original source of its anger, and presented with a constant series of new targets to swarm and sting, a swarm can continue its rampage nonstop until it is destroyed or dispersed.","ecology":"","habitat_society":""},{"name":"Wax Golem","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"construct","init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":15,"ac_touch":9,"ac_flat_footed":15,"ac_mods":"-1 Dex, +6 natural","hp":42,"hd":"4d10+20","hdvalue":4,"fort":1,"ref":0,"will":1,"immunities":["cold","construct traits","magic"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":30}],"melee":"slam +6 (1d6+3)","space":"5 ft.","reach":"5 ft.","strength":14,"dexterity":9,"wisdom":11,"charisma":1,"baseatk":4,"cmb":6,"cmd":15,"sq":[{"type":"conditional sentience"}],"environments":["any"],"organizations":["solitary","gang (2-4)"],"treasure":"none","description_visual":"This eerily expressionless woman has a glistening quality about her, as though she's covered in an oily sheen.","group":"Golem","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Conditional Sentience","kind":"Su","details":"A wax golem constructed to look like a humanoid (whether a particular individual or not) has a small chance of gaining sentience and genuinely believing it is a living creature. Each week, such a wax golem has a cumulative 1% chance of becoming sentient (on the second week the chance is 2%, the third week 3%, and so on), to a maximum of 5%. If it does attain sentience, the golem gains an Intelligence score of 10, retroactive skill points, feats dependent on its Hit Dice, and 1 class level with the potential to gain more. If it was crafted to resemble a specific individual, it also gains a +10 racial bonus on Disguise checks made to impersonate that individual. A sentient wax golem ventures into the world and tries to live a life similar to that of the person (or type of person) it resembles. However, if the sentient wax golem ever encounters the person it is modeled after, it attempts to stealthily kill that person and take her place. The only way for a sentient wax golem to lose its sentience is either to take an amount of fire damage equal to half its hit points (which melts its features away) or to be destroyed."},{"type":"Immunity to Magic","kind":"Ex","details":"A wax golem is immune to any spell or spell-like ability that allows spell resistance, with the exception of spells and spell-like abilities that have the fire descriptor. In addition, certain spells and effects function differently against the creature, as noted below. • A magical attack that deals fire damage slows a wax golem (as the slow spell) for 2d6 rounds (no save). In addition, for 3 rounds after taking fire damage, every time a wax golem uses its slam attack, it deals an additional 1d4 points of fire damage due to its molten wax. • A magical attack that deals cold damage breaks any slow effect on the golem and heals 1 point of damage for each 3 points of damage the attack would otherwise deal. If the amount of healing would cause the golem to exceed its full normal hit points, it gains any excess as temporary hit points. A wax golem gains no saving throw against cold effects."}],"description":"A wax golem is an exact replica of a particular person, composed completely of wax. While skilled artists pride themselves on their ability to make wax sculptures look lifelike, builders of wax golems go one step further and actually bring their art to life. Though eerily silent and unblinking, well-built wax golems bear such striking similarity to the subjects they are modeled after that some golems begin to think they are in fact that person. A wax golem can be constructed to resemble any person or creature.\n\nConstruction\n\nThe construction of a wax golem requires a block of solid wax that weights at least 1,000 pounds.\n\nWAX GOLEM\n\nCL 9th; Price 14,000 gp\n\nConstruction\n\nRequirements Craft Construct, animate objects, geas/quest, limited wish, silent image, creator must be caster level 9th; Skill Craft (sculptures) DC 18 (DC 25 if the creator wants the golem to look like a member of a particular race; DC 30 if the creator wants the golem to look like a specific individual); Cost 7,000 gp","ecology":"","habitat_society":""},{"name":"Werebat","cr":3,"xp":800,"race":"Human natural werebat","classes":[{"class":"rogue","level":3}],"alignment":"NE","size":"Medium","type":"humanoid","subtypes":["human","shapechanger"],"init":2,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":14,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+2 armor, +2 Dex","hp":23,"hd":"3d8+6","hdvalue":3,"fort":3,"ref":5,"will":3,"save_mods":"Ref: +1 vs. traps","defensive_abilities":["evasion","trap sense +1"],"speed":[{"type":"land","speed":30}],"melee":"mwk short sword +6 (1d6+2/19-20)","ranged":"mwk shortbow +5 (1d6/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"}],"strength":14,"dexterity":15,"constitution":15,"intelligence":10,"wisdom":14,"charisma":6,"baseatk":2,"cmb":4,"cmd":16,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Combat Reflexes"},{"feat":"Weapon Focus (short sword)"}],"skills":[{"skill":"Acrobatics","value":8},{"skill":"Climb","value":8},{"skill":"Disable Device","value":8},{"skill":"Disguise","value":4},{"skill":"Handle Animal","value":1},{"skill":"Intimidate","value":4},{"skill":"Perception","value":8},{"skill":"Sense Motive","value":8},{"skill":"Sleight of Hand","value":8},{"skill":"Stealth","value":8}],"languages":["Common"],"sq":[{"type":"change shape","details":"human, hybrid, and bat; polymorph"},{"type":"lycanthropic empathy","details":"bats and dire bats"},{"type":"rogue talents","details":"ledge walker"},{"type":"trapfinding","details":"+1"}],"environments":["temperate forests","temperate hills"],"organizations":["solitary","pair","gang (3-5)"],"treasure":"none","description_visual":"This furred humanoid has protruding fangs and thin membranes of tissue connecting its arms to its sides.","group":"Lycanthrope","source":"PFRPG Bestiary 4","description":"Werebats are hybrids of vampiric bats and humanoids, possessed of a ravenous bloodlust. As opposed to vampires, with which werebats are often confused, these lycanthropes are often more savage and less calculating than the shapeshifting undead. As though to prove a point, some werebats go out of their way to take down powerful vampire lords and commandeer the vampires' positions- though many also become slaves to such undead after underestimating their prowess. Natural werebats typically look like normal members of their humanoid parent race, though they often have dark hair, lithe frames, severe features, and slightly pointed ears. They typically stand taller than normal for their race, but weigh significantly less.","ecology":"","habitat_society":"","gear":"leather armor, mwk shortbow with 20 arrows, mwk short sword"},{"name":"Werebat","cr":3,"xp":800,"alignment":"NE","size":"Medium","type":"humanoid","subtypes":["human","shapechanger"],"init":2,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":16,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+2 armor, +2 Dex, +2 natural","hp":26,"hd":"3d8+9","hdvalue":3,"fort":4,"ref":5,"will":3,"save_mods":"Ref: +1 vs. traps","defensive_abilities":["evasion","trap sense +1"],"dr":"10/silver","speed":[{"type":"land","speed":30},{"type":"fly","speed":40,"maneuverability":"average"}],"melee":"bite +5 (1d6+3), 2 claws +5 (1d4+3)","ranged":"mwk shortbow +5 (1d6/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"curse of lycanthropy"},{"type":"sneak attack","details":"+2d6"}],"strength":16,"dexterity":15,"constitution":17,"intelligence":10,"wisdom":14,"charisma":6,"baseatk":2,"cmb":4,"cmd":17,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Combat Reflexes"},{"feat":"Weapon Focus (short sword)"}],"skills":[{"skill":"Acrobatics","value":8},{"skill":"Climb","value":9},{"skill":"Disable Device","value":8},{"skill":"Disguise","value":4},{"skill":"Handle Animal","value":1},{"skill":"Intimidate","value":4},{"skill":"Perception","value":8},{"skill":"Sense Motive","value":8},{"skill":"Sleight of Hand","value":8},{"skill":"Stealth","value":8}],"languages":["Common"],"sq":[{"type":"change shape","details":"human, hybrid, and bat; polymorph"},{"type":"lycanthropic empathy","details":"bats and dire bats"},{"type":"rogue talents","details":"ledge walker"},{"type":"trapfinding","details":"+1"}],"environments":["temperate forests","temperate hills"],"organizations":["solitary","pair","gang (3-5)"],"treasure":"none","description_visual":"This furred humanoid has protruding fangs and thin membranes of tissue connecting its arms to its sides.","group":"Lycanthrope","source":"PFRPG Bestiary 4","description":"Werebats are hybrids of vampiric bats and humanoids, possessed of a ravenous bloodlust. As opposed to vampires, with which werebats are often confused, these lycanthropes are often more savage and less calculating than the shapeshifting undead. As though to prove a point, some werebats go out of their way to take down powerful vampire lords and commandeer the vampires' positions- though many also become slaves to such undead after underestimating their prowess. Natural werebats typically look like normal members of their humanoid parent race, though they often have dark hair, lithe frames, severe features, and slightly pointed ears. They typically stand taller than normal for their race, but weigh significantly less.","ecology":"","habitat_society":"","gear":"leather armor, mwk shortbow with 20 arrows, mwk short sword"},{"name":"Werecrocodile","cr":3,"xp":800,"race":"Human natural werecrocodile","classes":[{"class":"fighter","level":3}],"alignment":"NE","size":"Medium","type":"humanoid","subtypes":["human","shapechanger"],"init":5,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":11,"ac_touch":11,"ac_flat_footed":10,"ac_mods":"+1 Dex","hp":27,"hd":"3d10+6","hdvalue":3,"fort":7,"ref":2,"will":2,"save_mods":"Will: +1 vs. fear","defensive_abilities":["bravery +1"],"speed":[{"type":"land","speed":30}],"melee":"mwk battleaxe +7 (1d8+3/x3)","space":"5 ft.","reach":"5 ft.","strength":17,"dexterity":13,"constitution":14,"intelligence":12,"wisdom":12,"charisma":6,"baseatk":3,"cmb":6,"cmd":17,"feats":[{"feat":"Cleave"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Run"}],"skills":[{"skill":"Intimidate","value":4},{"skill":"Perception","value":4},{"skill":"Stealth","value":5},{"skill":"Survival","value":7},{"skill":"Swim","value":11}],"languages":["Common"],"sq":[{"type":"armor training","details":"1"},{"type":"change shape","details":"human, hybrid, and crocodile; polymorph"},{"type":"lycanthropic empathy","details":"crocodiles and dire crocodiles"}],"environments":["warm marshes","warm rivers"],"organizations":["solitary","pair","colony (3-12)"],"treasure":"none","description_visual":"Standing taller than a man, this humanoid figure wears filth-covered rags over its scaly form.","group":"Lycanthrope","source":"PFRPG Bestiary 4","description":"Werecrocodiles merge the ruthless determination of a crocodile with the intelligence and adaptability of a humanoid. This fusion creates a maliciously cunning creature with no doubt of its own martial superiority.","ecology":"","habitat_society":"","gear":"mwk battleaxe"},{"name":"Werecrocodile","cr":3,"xp":800,"alignment":"NE","size":"Medium","type":"humanoid","subtypes":["human","shapechanger"],"init":5,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":23,"ac_touch":11,"ac_flat_footed":16,"ac_mods":"+1 Dex, +6 natural","hp":30,"hd":"3d10+9","hdvalue":3,"fort":8,"ref":2,"will":2,"save_mods":"Will: +1 vs. fear","defensive_abilities":["bravery +1"],"dr":"10/silver","speed":[{"type":"land","speed":30},{"type":"swim","speed":20}],"speed_mod":"sprint","melee":"bite +7 (1d8+4 plus grab and curse of lycanthropy), tail slap +2 (1d12+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"curse of lycanthropy"},{"type":"death roll","details":"1d8+4 plus trip"},{"type":"grab"}],"strength":19,"dexterity":13,"constitution":16,"intelligence":12,"wisdom":12,"charisma":6,"baseatk":3,"cmb":7,"cmb_special":"+4 vs. grapple","cmd":18,"feats":[{"feat":"Cleave"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Run"}],"skills":[{"skill":"Intimidate","value":4},{"skill":"Perception","value":4},{"skill":"Stealth","value":5},{"skill":"Survival","value":7},{"skill":"Swim","value":19}],"languages":["Common"],"sq":[{"type":"armor training","details":"1"},{"type":"change shape","details":"human, hybrid, and crocodile; polymorph"},{"type":"hold breath"},{"type":"lycanthropic empathy","details":"crocodiles and dire crocodiles"},{"type":"sprint"}],"environments":["warm marshes","warm rivers"],"organizations":["solitary","pair","colony (3-12)"],"treasure":"none","description_visual":"Standing taller than a man, this humanoid figure wears filth-covered rags over its scaly form.","group":"Lycanthrope","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Death Roll","kind":"Ex","details":"When grappling a foe of its size or smaller, a werecrocodile can perform a death roll upon making a successful grapple check. As it clings to its foe, the werecrocodile deals its bite damage, knocks the creature prone, and maintains the grapple."},{"type":"Sprint","kind":"Ex","details":"Once per minute, a werecrocodile can increase its land speed to 60 ft. for 1 round."}],"description":"Werecrocodiles merge the ruthless determination of a crocodile with the intelligence and adaptability of a humanoid. This fusion creates a maliciously cunning creature with no doubt of its own martial superiority.","ecology":"","habitat_society":"","gear":"mwk battleaxe"},{"name":"Wereshark","cr":3,"xp":800,"race":"Human natural wereshark","classes":[{"class":"fighter","level":3}],"alignment":"CE","size":"Medium","type":"humanoid","subtypes":["human","shapechanger"],"init":1,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":11,"ac_touch":11,"ac_flat_footed":10,"ac_mods":"+1 Dex","hp":33,"hd":"3d10+12","hdvalue":3,"fort":5,"ref":2,"will":3,"save_mods":"Will: +1 vs. fear","defensive_abilities":["bravery +1"],"speed":[{"type":"land","speed":30}],"melee":"mwk trident +9 (1d8+3)","space":"5 ft.","reach":"5 ft.","strength":17,"dexterity":12,"constitution":14,"intelligence":8,"wisdom":15,"charisma":8,"baseatk":3,"cmb":6,"cmd":17,"feats":[{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Weapon Focus (trident)"}],"skills":[{"skill":"Survival","value":8},{"skill":"Swim","value":10}],"languages":["Common"],"sq":[{"type":"armor training","details":"1"},{"type":"change shape","details":"human, hybrid, and shark; polymorph"},{"type":"lycanthropic empathy","details":"sharks and dire sharks"}],"environments":["any coastlines","any oceans"],"organizations":["solitary","pair","shiver (3-6)"],"treasure":"none","description_visual":"This muscular creature has a human body, but the head of a ravenous shark, complete with jet-black eyes and razorlike teeth.","group":"Lycanthrope","source":"PFRPG Bestiary 4","description":"In either humanoid or hybrid form, a wereshark is generally burly, has a mouth full of unusually large teeth, and typically has a personality that is both crude and bullying. They're bloodthirsty and are very easy to anger. They will jump into fights they have no stake in just to snap bones and draw blood. Weresharks prefer life at sea or in port settlements commonly frequented by seagoing merchants and pirates. They can be found leading pirate gangs or loitering at seaside taverns accompanied by crowds of toadies. Since they get into fights so often, they try to stick close to the sea so they can escape into the water if they bite off more than they can chew. The other members of a wereshark's crew learn quickly that the boss is bound to skip out without much notice once a bigger fish comes along.","ecology":"","habitat_society":"","gear":"mwk trident"}];
